program.compute:
options = read('/input/options')
result = []
for n in range(3, 4):
    for group in combinations(options, n):
        ids = [item['id'] for item in group]
        if valid(ids):
            result = ids
            break
    if len(result) > 0:
        break

program.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    selection = result
    write('/output/selection', selection)
if status('report') == 'not_sent':
    send('report', 'team', selection)
elif status('report') == 'sent':
    pass
else:
    send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')

